body.userscript:


            //폼, smr_number등의 정보를 담는 변수



            //그리드 데이터의 정보를 담는 변수



            //날인서류인장리스트








            //새로 만든 요청이라면 Y






            switch (name) {
                case "SAVE":
                    doSave();
                    break;
                case "APPROVAL_REQUEST":
                    doApprovalRequest();
                    break;
                case "MANAGER_REQUEST":
                    doManagerRequest();
                    break;
                case "MANAGER_ACCEPT":
                    doManagerAccept();
                    break;
                case "MANAGER_REJECT":
                    doManagerReject();
                    break;
                case "BACK":
                    doBack();
                    break;
                case "RETURN_REQUEST":
                    doReturnRequest();
                    break
                case "RETURN_COMPLETE":
                    doReturnComplete();
                    break
                default:
                    break;
            }




            //용도 버튼
            if (name == 'SEAL_USE_TYPE_BTN') {
                PopupCommonPost('SP0069', sealUseTypePopupCallback, [Sepoa.info.HOUSE_CODE, Sepoa.info.COMPANY_CODE]);
            }




            formObj.setValue('SEAL_USE_TYPE', c);
            formObj.setValue('SEAL_USE_TYPE_LOC', b)





            // 채번 따서 $reqExtInfo에 채번넣고 기본셋팅
            $documentList = new Object(); //문서정보리스트
            $selectedExtList = new Object(); //인장리스트

            //그리드 셋팅
            gridObj_title.innerHTML = Sepoa.cache.text.get('SLM_501.GRID_TITLE');
            gridObj_title.setAttribute('style', 'font-size:14px;padding-top: 15px;');
            gridObj.setColumnHidden(gridObj.getColIndexById('SEAL_TYPE'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('REAL_FLAG'), true);
            gridObj.setColumnHidden(gridObj.getColIndexById('ATTACH2_IMG'), true);

            //폼 셋팅
            formObj.getInput("EXT_OUT_EXPECT_DATE").placeholder = Sepoa.cache.text.get('SLM_501.EXT_OUT_YYYYMMDD'); //반출년월일
            formObj.getInput("EXT_IN_EXPECT_DATE").placeholder = Sepoa.cache.text.get('SLM_501.EXT_IN_YYYYMMDD'); //반입년월일
            formObj.setValue("SEAL_USE_TYPE", '1');

            /*formObj_1.setValue('EXT_USE_USER_ID', Sepoa.info.ID);
            formObj_1.setValue('EXT_USE_USER_NAME_LOC', Sepoa.info.NAME_LOC);
            formObj_1.setValue('EXT_USE_DEPT_NAME_LOC', Sepoa.info.DEPARTMENT_NAME_LOC);
            formObj_1.hideItem("EXT_OUT_DATE");
            formObj_1.hideItem("EXT_OUT_HOUR");
            formObj_1.hideItem("EXT_OUT_MINUTE");
            formObj_1.hideItem("EXT_IN_DATE");
            formObj_1.hideItem("EXT_IN_HOUR");
            formObj_1.hideItem("EXT_IN_MINUTE");*/

            //폼 셋팅
            formObj.checkItem('REAL_FLAG');
            formObj.setReadonly('REAL_FLAG', true);

            if (Sepoa.request.TYPE) {
                aliasType = Sepoa.request.TYPE;
            }

            if (sUtils.ux.getRootScreenID() == 'SLM_500') {
                var smrNumber = Sepoa.request.SMR_NUMBER || getDocumentNumber("SER"); //채번
                $reqExtInfo.SMR_NUMBER = smrNumber;
                formObj.setValue('SMR_NUMBER', smrNumber);

                initBtn();
            }




            btnObj.forEachBtn(function(btnId) {
                if (btnId) {
                    btnObj.showButton(btnId, false);
                }
            });
            gridObj_btnObj.forEachBtn(function(btnId) {
                if (btnId) {
                    gridObj_btnObj.showButton(btnId, false);
                }
            });




            document.getElementById('GGeujmeXdkujmeKLSb').style.display = 'inline-block';
            document.getElementById('GGeujmeoArxjmeFbFw').style.display = 'inline-block';




            if (mode) editMode = mode;




            // 처음에 모든 버튼을 숨기고 상황에 맞는 버튼 표출
            hideAllButtons();

            if (editMode == 'APP') {
                formObj._apiConnector('detachAllEvents', []);
                formObj.setViewMode(true);
                //formObj_1.setViewMode(true);
                gridObj.setReadOnly(true);
                showButtonArea();
            } else if (smrStatus != 'T' && smrStatus != 'F' && smrStatus != 'RW' && smrStatus != 'R') { //임시저장 또는 반려가 아닌 경우 
                var alias = '';
                formObj._apiConnector('detachAllEvents', []); //폼의 이벤트와 분리
                formObj.setViewMode(true);
                //formObj_1.setViewMode(true);
                gridObj.setReadOnly(true);
                btnObj.showButton('back', true);
                gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 1); //관리부서 선택버튼 숨김

                if (Sepoa.request.SMR_NUMBER || ['APP', 'APPR_TURN', 'APPR_DONE'].indexOf(editMode) > -1) {
                    btnObj.showButton('back', false);
                }

                if (smrStatus == 'RR' && btnFlag) {
                    alias = 'MANAGER';
                }

                if (smrStatus == 'W' && btnFlag) { //인감관리자 승인 진행중
                    alias = 'APPROVAL';
                }

                if (alias != '') { //alias가 MANAGER 일 경우 다음 진행상황에 따른 버튼 표출
                    doServiceAjax('sepoa.svc.seal.SepoaReqExternalService', 'CONNECTION', 'doSelectNextModule', { //반출 요청시 서비스
                        ALIAS: alias,
                        PARENT: 'ET'
                    }, function(so) {
                        if (so.status == 1) {
                            var moduleArr = JSON.parse(so.result[0]);
                            var nextModule = moduleArr.MODULE;
                            switch (nextModule) {
                                case "ET1644372420935":
                                    // 결재
                                    btnObj.showButton('approval_request', true);
                                    break;
                                case "ET1644374538390":
                                    // 인감관리자 승인
                                    btnObj.showButton('manager_reject,manager_accept', true);
                                    break;
                                case "ET1647222908416":
                                    //반납요청
                                    btnObj.showButton('return_complete', true);
                                    break;
                                case "ET1644375000197":
                                    // 완료
                                    btnObj.showButton('complete', true);
                                    break;
                                default:
                                    break;
                            }
                        } else {
                            Alert(Sepoa.cache.text.get("MESSAGE.1002")); //오류발생
                        }
                    });
                }
                showButtonArea();
            } else if (smrStatus == 'T' || smrStatus == 'F' || smrStatus == 'RW' || smrStatus == 'R') { //임시저장, 새로운 요청 또는 반려일 경우
                if (moveFlag == 'N') { //기존 임시저장일 경우 N, Y는 요청내역에서 들어올 시 doquery에서 Y을 들고 들어옴 
                    btnObj.showButton('back', true);
                }

                if (smrStatus == 'T') { // 이전반려사유 보이기 유무
                    formObj.hideItem('REJECT_REMARK');
                } else {
                    formObj.showItem('REJECT_REMARK');
                }

                //다음 모듈을 실행하기 위한 alias 셋팅
                var alias = '';
                alias = 'CREATE';
                if (smrStatus == 'RW' && !btnFlag) {
                    alias = 'MANAGER';
                } else if (smrStatus == 'RW') {
                    alias = '';
                    showButtonArea();
                    btnObj.showButton('back', true);
                } else if (smrStatus == 'A' || smrStatus == 'F') {
                    alias = 'APPROVAL';
                }
                gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), 0); //관리부서 선택버튼 표출
                gridObj_btnObj.showButton('rowadd,rowdelete', true); //행 추가,삭제버튼 표출
                // 임시저장 상태일 때 다음 모듈에 따라 표출될 버튼이 다름
                // PARENT: 어느 페이지 안에서 서비스를 실행하는지 확인
                if (alias != '') { //alias가 MANAGER 일 경우 다음 진행상황에 따른 버튼 표출
                    doServiceAjax('sepoa.svc.seal.SepoaReqExternalService', 'CONNECTION', 'doSelectNextModule', {
                        ALIAS: alias,
                        PARENT: 'ET'
                    }, function(so) {
                        if (so.status == 1) {
                            var moduleArr = JSON.parse(so.result[0]);
                            var nextModule = moduleArr.MODULE;

                            switch (nextModule) {
                                case "ET1644372420935":
                                    // 결재
                                    if (editMode == 'VIEW') {
                                        //btnObj.showButton('approval_request', true);
                                    } else {
                                        btnObj.showButton('save,approval_request', true);
                                    }
                                    break;
                                case "ET1644374538390":
                                    // 인감관리자 승인
                                    if (editMode == 'VIEW') {
                                        //btnObj.showButton('manager_request', true);
                                    } else {
                                        btnObj.showButton('save,manager_request', true);
                                    }
                                    break;
                                case "ET1647222908416":
                                    //반납요청
                                    if (!btnFlag) {
                                        btnObj.showButton('return_request', true);
                                    } else {
                                        btnObj.showButton('back', true);
                                    }
                                    break;
                                case "ET1644375000197":
                                    // 완료
                                    btnObj.showButton('complete', true);
                                    break;
                                default:
                                    break;
                            }
                            showButtonArea();
                        } else {
                            Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                        }
                    });
                }
            }




            $documentList = {};
            $reqExtInfo = {};
            formObj.clear();
            //formObj_1.clear();
            gridObj.clearAll();
            moveFlag = flag;
            editMode = mode;
            formObj.setValue("SEAL_USE_TYPE", '1');
            var app_type = applyType;
            doServiceAjax('sepoa.svc.seal.SepoaReqExternalService', 'CONNECTION', 'doSelectRequestInfo', { // 반출 요청의 정보를 조회
                SMR_NUMBER: smrNumber,
                APPLY_TYPE: app_type
            }, function(so) {
                if (so.status == 1) {
                    var reqData = JSON.parse(so.result[0]);
                    var reqExtInfo = reqData[0].REQ_EXT_INFO; //객체정보
                    var documentList = reqData[0].DOCUMENT_LIST; //서류문서
                    var selectedExtList = reqData[0].SELECTED_EXT_LIST; //인감조회
                    var btnFlag = false;
                    formObj.dataMapper(reqExtInfo, 'JSON');
                    //formObj_1.dataMapper(reqExtInfo, 'JSON');
                    $reqExtInfo.SMR_NUMBER = reqExtInfo.SMR_NUMBER;

                    smrStatus = reqExtInfo.SMR_STATUS;

                    if ((smrStatus == 'RW' || smrStatus == 'RR' || smrStatus == 'C') && sUtils.workflow.check('ET1647222908416')) { //
                        gridObj.setColumnHidden(gridObj.getColIndexById('ATTACH2_IMG'), false);
                    }

                    // 구분 세팅
                    formObj.setValue('REAL_FLAG', 1);

                    //콤보 불러오기
                    var useArray = Sepoa.cache.combo.get('SP0069,' + Sepoa.info.HOUSE_CODE + '#' + Sepoa.info.COMPANY_CODE);
                    //배열의 특정값을 찾는 조건을 callback함수를 통해 전달하여 조건에 맞는 값 중 첫번째 값을 리턴한다.
                    //EX ) arr.find(callback(element[,index[,array]])[,thisArg])
                    //item = 현재 처리중인 배열의 element, idx = 현재 처리중인 배열의 인덱스
                    var useName = useArray.find((item, idx) => {
                        return item.text == reqExtInfo.SEAL_USE_TYPE; //요청된 용도와 해당 값이 같으면
                    });

                    // 용도 세팅
                    if (useName != null && useName != '') {
                        formObj.setValue('SEAL_USE_TYPE', useName.text); //용도 코드번호
                        formObj.setValue('SEAL_USE_TYPE_LOC', useName.value); //용도명
                    }

                    for (var i in documentList) {
                        var data = documentList[i];
                        var maxRowId = dhx4.newId();
                        // 그리드 데이터 셋팅
                        gridObj.addRow(maxRowId, '', gridObj.getRowsNum());
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SMD_NUMBER')).setValue(data.SMD_NUMBER); //날인서류채번
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_DEPT_LOC')).setValue(data.DEPT_NAME);
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_DEPT')).setValue(data.SEAL_MG_DEPT);
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_MG_USER_ID')).setValue(data.SEAL_MG_USER_ID);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_NO')).setValue(data.ATTACH_NO);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH2_NO')).setValue(data.ATTACH2_NO);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('DOWN_COUNT')).setValue(data.DOWN_COUNT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SUBJECT')).setValue(data.SUBJECT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SEAL_TYPE')).setValue(data.SEAL_TYPE);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('MANAGE_NUMBER')).setValue(data.MANAGE_NUMBER);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('DOC_NUMBER')).setValue(data.SMR_NUMBER + '_' + data.SMD_NUMBER);
                        //gridObj.cells(maxRowId, gridObj.getColIndexById('CALC_DOWN_CNT')).setValue(Number(data.COUNT) - Number(data.DOWN_COUNT));
                        gridObj.cells(maxRowId, gridObj.getColIndexById('COUNT')).setValue(data.COUNT);
                        gridObj.cells(maxRowId, gridObj.getColIndexById('SMR_SEQ')).setValue(data.SMR_SEQ);
                        gridObj.showRow(maxRowId);

                        if (gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_NO')).getValue() != '') {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                        }
                        if (gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH2_NO')).getValue() != '') {
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH2_IMG')).setIcon('ATTACH_IMG2');
                            gridObj.cells(maxRowId, gridObj.getColIndexById('ATTACH2_IMG')).cell.children[0].style = 'filter:none';
                        }

                        $documentList[data.SMD_NUMBER] = data;
                        $selectedExtList[data.SMD_NUMBER] = {};
                        var sealData = [];
                        //인장 리스트
                        for (var j in selectedExtList) {
                            if (data.SMD_NUMBER == selectedExtList[j].SMD_NUMBER) {
                                selectedExtList[j].ITEM_NAME = selectedExtList[j].SUBJECT;
                                sealData.push(selectedExtList[j]);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT_LOC")).setValue(selectedExtList[j].DEPT_NAME);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_DEPT")).setValue(selectedExtList[j].SEAL_MG_DEPT);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_USER_ID")).setValue(selectedExtList[j].SEAL_MG_USER_ID);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_USER_NAME")).setValue(selectedExtList[j].SEAL_MG_USER_NAME);
                                gridObj.cells(maxRowId, gridObj.getColIndexById("SEAL_MG_SUBJECT")).setValue(selectedExtList[j].SUBJECT);
                                sealMgId.push(selectedExtList[j].SEAL_MG_USER_ID);
            					debugger;
                                if (smrStatus == 'W' && Sepoa.info.ID == selectedExtList[j].SEAL_MG_USER_ID && selectedExtList[j].ACCEPT_FLAG == 'N') {
                                    btnFlag = true;
                                }
                                if (smrStatus == 'RW' && Sepoa.info.ID == selectedExtList[j].SEAL_MG_USER_ID) {
                                    btnFlag = false;
                                }
                                if (smrStatus == 'RR' && Sepoa.info.ID == selectedExtList[j].SEAL_MG_USER_ID && selectedExtList[j].COMPLETE_FLAG == 'N') {
                                    btnFlag = true;
                                }
                                if (smrStatus == 'W' && Sepoa.info.ID == selectedExtList[j].RECE_USER_ID && selectedExtList[j].ACCEPT_FLAG == 'N'){
                                	btnFlag = true;
                                }
                            }
                        }
                        $documentList[data.SMD_NUMBER].SELECT_EXT_LIST = sealData;
                        $selectedExtList[data.SMD_NUMBER].SELECT_EXT_LIST = sealData;
                    }
                    initBtn(btnFlag, editMode);
                    doChangeEditMode(editMode);
                } else {
                    Alert(Sepoa.cache.text.get("MESSAGE.1002"));
                }
            });




            callFunction('p', 'doBack', []);




            switch (editMode) {
                case "VIEW": // 뷰
                    formObj.setViewMode(true);
                    formObj.setdisable('SEAL_USE_TYPE_BTN', true);
                    //formObj_1.setdisable('EXT_USE_USER_IMG', true);
                    //formObj_1.setViewMode(true);

                    gridObj.setEditable(false);
                    gridObj.setColumnHidden(gridObj.getColIndexById('SELECTED'), true);
                    gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), true);
                    gridObj_btnObj.showButton('rowadd,rowdelete', false); //행 추가,삭제버튼 표출

                    break;
                case "EDITOR": // 수정
                    formObj.setViewMode(false);
                    formObj.setdisable('SEAL_USE_TYPE_BTN', false);
                    //formObj_1.setdisable('EXT_USE_USER_IMG', false);
                    //formObj_1.setViewMode(false);

                    gridObj.setReadOnly(false);
                    gridObj.setEditable(true);
                    gridObj.setColumnHidden(gridObj.getColIndexById('SELECTED'), false);
                    gridObj.setColumnHidden(gridObj.getColIndexById('MANAGE_IMG'), false);
                    gridObj_btnObj.showButton('rowadd,rowdelete', true); //행 추가,삭제버튼 표출

                    break;
                case "undefined": //doSave이후 화면이전시
                    formObj.clear();
                    //formObj_1.clear();
                    gridObj.clearAll();
                default:
                    break;
            }




        	//var formData = Object.assign(formObj.getFormData(), formObj_1.getFormData());
            var formData = Object.assign(formObj.getFormData());
            formData.SEAL_USE_TYPE = formObj.getValue('SEAL_USE_TYPE'); //용도의 값
            formData.REMARK = formObj.getValue('REMARK'); //사외반출 필요사유
            formData.APPLY_TYPE = 'U'; //반출 -> 반출 신청 시 인감 구분을 위한 것으로 추정(사용인감(U) or 서명인(E))
            formData.EXT_OUT_EXPECT_DATE = formObj.getValue('EXT_OUT_EXPECT_DATE'); // 예상사외반출일
            formData.EXT_IN_EXPECT_DATE = formObj.getValue('EXT_IN_EXPECT_DATE'); // 예상사내반입일
            formData.REJECT_REMARK = reject_comment; // 승인/반려사유
            formData.EXT_USE_USER_ID = Sepoa.info.ID; // 반출 요청자(세션 ID)
            $reqExtInfo = formData; // 반출 요청 정보(폼)

            // 날인예상서류의 행을 담을 배열
            var documentArr = new Array();
            gridObj.forEachRowA(function(id) { //날인대상서류의 행의 값들을 배열에 넣음
                var documentData = {};
                var smdNumber = gridObj.cells(id, gridObj.getColIndexById('SMD_NUMBER')).getValue(); //날인서류 채번
                documentData.SMD_NUMBER = smdNumber;
                documentData.SEAL_TYPE = gridObj.cells(id, gridObj.getColIndexById('SEAL_TYPE')).getValue();
                documentData.SEAL_MG_DEPT = gridObj.cells(id, gridObj.getColIndexById('SEAL_MG_DEPT')).getValue();
                documentData.SEAL_MG_USER_ID = gridObj.cells(id, gridObj.getColIndexById('SEAL_MG_USER_ID')).getValue();
                documentData.SEAL_MG_SUBJECT = gridObj.cells(id, gridObj.getColIndexById('SEAL_MG_SUBJECT')).getValue(); // 인감명
                documentData.SUBJECT = gridObj.cells(id, gridObj.getColIndexById('SUBJECT')).getValue(); // 서류명
                documentData.COUNT = String(gridObj.cells(id, gridObj.getColIndexById('COUNT')).getValue()); // 부수
                // documentData.SMD_NUMBER = gridObj.cells(id, gridObj.getColIndexById('SMD_NUMBER')).getValue(); // 중복으로 smd_number 세팅
                documentData.SELECT_EXT_LIST = $selectedExtList[smdNumber].SELECT_EXT_LIST; // 날인서류에 해당하는 인감리스트
                documentData.DOC_NUMBER = gridObj.cells(id, gridObj.getColIndexById('DOC_NUMBER')).getValue();
                documentData.ATTACH_NO = gridObj.cells(id, gridObj.getColIndexById('ATTACH_NO')).getValue(); // 날인서류 파일 번호
                documentData.ATTACH2_NO = gridObj.cells(id, gridObj.getColIndexById('ATTACH2_NO')).getValue(); // 실사용 날인서류 파일 번호
                documentData.MANAGE_NUMBER = gridObj.cells(id, gridObj.getColIndexById('MANAGE_NUMBER')).getValue(); // 인감관리번호
                documentData.SMR_SEQ = gridObj.cells(id, gridObj.getColIndexById('SMR_SEQ')).getValue();
                documentData.DELROW_DATA = deleteRows; //삭제예정(서비스 로직에서 삭제될 데이터들)
                documentArr.push(documentData);
            });

            $documentList = documentArr;
            /*if (!callbackObj) { //없다면
                var value = searchExtAjax(formData);
                if (!value) {
                    return;
                }
            } else if (callbackObj) { //있다면
                var callback_parm = callbackObj.CALLBACK_PARMETER;
                if (callback_parm && ["MANAGER_REQUEST","APPROVAL_REQUEST"].indexOf(callback_parm['LEGAL_PRC_TYPE']||callback_parm['APPROVAL_PRC_TYPE']) > -1) {
                    var value = searchExtAjax(formData);
                    if (!value) {
                        return;
                    }
                }
            }*/

            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                            if (callbackObj) { //임시저장이 아닌경우 callbackObj를 인자값으로 받음
                                callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
                            } else {
                                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                                if (moveFlag == 'Y') { //새로 만든 요청이라면 
                                    linkTo('SLM_510', '/Seal/Document/External/Request/SealExternalRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_501.REQUEST_LIST'));
                                    SUX.root.getContentsCell(window).close();
                                } else {
